                                                                                                                                                                                                                
  CREATE TABLE "TENANT_ROBOT_SUBSCRIBE"                                                                                                                                                              
   (	"ROBOT_SUBSCRIBE_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                                     
	"CREATION_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                          
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                                     
	"UPDATE_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                            
	"REMARK" NVARCHAR2(512),                                                                                                                                                                                       
	"CONVERSATION_NAME" NVARCHAR2(64) NOT NULL ENABLE,                                                                                                                                                             
	"CONVERSATION_ID" NVARCHAR2(64) NOT NULL ENABLE,                                                                                                                                                               
	"CHATBOT_ID" NVARCHAR2(64),                                                                                                                                                                                    
	"CORP_ID" NVARCHAR2(128),                                                                                                                                                                                      
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                            
	"ROBOT_ID" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                                       
	"DEPT_ID" NUMBER(20,0) DEFAULT 0,                                                                                                                                                                              
	"IS_ENABLE" NUMBER(1,0) DEFAULT 1,                                                                                                                                                                             
	"IS_JBNOTICE" NUMBER(1,0) DEFAULT 1,                                                                                                                                                                           
	"NOTICE_TIME" NUMBER(20,0) DEFAULT 60,                                                                                                                                                                         
	"IS_NOTICE" NUMBER(1,0) DEFAULT 1,                                                                                                                                                                             
	"FAB_ID" NUMBER(20,0) DEFAULT 0,                                                                                                                                                                               
	"TYPES" NUMBER(1,0) DEFAULT 1,                                                                                                                                                                                 
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                                  
	 PRIMARY KEY ("ROBOT_SUBSCRIBE_ID")                                                                                                                                                                            
  USING INDEX  ENABLE,                                                                                                                                                                                          
	 CONSTRAINT "UNIQUE_ROBOT_SUBSCRIBE" UNIQUE ("CONVERSATION_ID", "TENANT_ID", "DEPT_ID", "IS_ENABLE", "IS_JBNOTICE", "NOTICE_TIME", "IS_NOTICE", "FAB_ID", "TYPES")                                             
  USING INDEX  ENABLE                                                                                                                                                                                           
   ) ;                                                                                                                                                                                                          

